<?php
namespace App\Models;
use App\Domain\Foundation\Traits\BelongsToCollege; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\SoftDeletes; use Illuminate\Database\Eloquent\Relations\BelongsTo;
class AcademicSubjectEnrollment extends Model { use BelongsToCollege, SoftDeletes; protected $table='academic_subject_enrollments'; protected $guarded=['id']; protected function casts():array{return ['enrollment_date'=>'date'];} public function student():BelongsTo{return $this->belongsTo(Student::class);} public function studentEnrollment():BelongsTo{return $this->belongsTo(StudentEnrollment::class);} public function academicYear():BelongsTo{return $this->belongsTo(AcademicYear::class);} public function academicTerm():BelongsTo{return $this->belongsTo(AcademicTerm::class);} public function program():BelongsTo{return $this->belongsTo(Program::class);} public function section():BelongsTo{return $this->belongsTo(Section::class);} public function subject():BelongsTo{return $this->belongsTo(Subject::class);} }
